inline const uint8_t* findHangulBitmap(uint16_t unicode) {
    int left = 0, right = static_cast<int>(HANGUL_GLYPH_COUNT) - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (HANGUL_GLYPHS[mid].unicode == unicode) {
            return HANGUL_GLYPHS[mid].bitmap;
        }
        if (HANGUL_GLYPHS[mid].unicode < unicode) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return nullptr;
}

